CREATE DATABASE SalesProjectDB;
USE SalesProjectDB;
SELECT * FROM [dbo].[Sales data Analysis using SQL];
SELECT COUNT(*) AS TotalRows FROM [dbo].[Sales data Analysis using SQL];
SELECT SUM(SalesAmount) AS TotalSales FROM [dbo].[Sales data Analysis using SQL];
SELECT SUM(SalesAmount) AS CompletedSales FROM [dbo].[Sales data Analysis using SQL] WHERE OrderStatus = 'Completed';
SELECT COUNT(*) AS CompletedOrders FROM [dbo].[Sales data Analysis using SQL] WHERE OrderStatus = 'Completed';
SELECT COUNT(*) AS CanceledOrders FROM [dbo].[Sales data Analysis using SQL] WHERE OrderStatus = 'Cancelled';
SELECT COUNT(*) AS ReturnedOrders FROM [dbo].[Sales data Analysis using SQL] WHERE OrderStatus = 'Returned';
SELECT City , SUM(SalesAmount) AS TotalCitysales FROM [dbo].[Sales data Analysis using SQL] GROUP BY City;
SELECT TOP 1 City , SUM(salesAmount) AS HighSalesCity FROM [dbo].[Sales data Analysis using SQL] GROUP BY City ORDER BY HighSalesCity DESC;
SELECT ProductName , SUM(SalesAmount) AS TotalProductSales FROM [dbo].[Sales data Analysis using SQL] GROUP BY ProductName ORDER BY TotalProductSales DESC;
SELECT PaymentMode,COUNT(*) AS TotalPaymentOrders FROM [dbo].[Sales data Analysis using SQL] GROUP BY PaymentMode ORDER BY TotalPaymentOrders DESC;
SELECT Category, SUM(SalesAmount) AS TotalCategory FROM [dbo].[Sales data Analysis using SQL] GROUP BY Category ORDER BY TotalCategory DESC;
SELECT City, COUNT(*) AS EveryCity FROM [dbo].[Sales data Analysis using SQL] GROUP BY City ORDER BY EveryCity DESC;
SELECT YEAR(OrderDate) AS SalesYear , MONTH(OrderDate) AS SalesMonth , SUM(SalesAmount) AS TotalSales FROM [dbo].[Sales data Analysis using SQL] GROUP BY YEAR(OrderDate) , MONTH(OrderDate) ORDER BY TotalSales DESC;
SELECT YEAR(OrderDate) AS SalesYear , MONTH(OrderDate) AS SalesMonth , SUM(SalesAmount) AS TotalSales FROM [dbo].[Sales data Analysis using SQL] GROUP BY YEAR(OrderDate) , MONTH(OrderDate) ORDER BY TotalSales ASC;
SELECT ProductName, SUM(Quantity) AS HighQuntity FROM [dbo].[Sales data Analysis using SQL] GROUP BY ProductName ORDER BY HighQuntity DESC;
SELECT ProductName, SUM(Quantity) AS LowQuntity FROM [dbo].[Sales data Analysis using SQL] GROUP BY ProductName ORDER BY LowQuntity ASC;
SELECT COUNT(*) AS CompletedOrder,COUNT(*) * 100.0/(SELECT COUNT(*) FROM [dbo].[Sales data Analysis using SQL])AS CompletedPercent FROM [dbo].[Sales data Analysis using SQL] WHERE OrderStatus = 'Completed';
SELECT OrderStatus , COUNT(*) AS TotalOrders, COUNT(*) * 100.0 /(SELECT COUNT(*) FROM [dbo].[Sales data Analysis using SQL]) AS OrderPercent FROM [dbo].[Sales data Analysis using SQL] GROUP BY OrderStatus;
SELECT AVG(SalesAmount) AS AverageSalesOrder FROM [dbo].[Sales data Analysis using SQL];
SELECT CustomerName,SUM(SalesAmount) AS TotalSales FROM [dbo].[Sales data Analysis using SQL] GROUP BY CustomerName ORDER BY TotalSales DESC;
SELECT CustomerName,SUM(SalesAmount) AS TotalSales FROM [dbo].[Sales data Analysis using SQL] GROUP BY CustomerName ORDER BY TotalSales ASC;
SELECT CustomerName , COUNT(*) AS TotalOrders FROM [dbo].[Sales data Analysis using SQL]  GROUP BY CustomerName ORDER BY  TotalOrders DESC ;
SELECT Category , AVG(SalesAmount) AS AverageSales FROM [dbo].[Sales data Analysis using SQL] GROUP BY Category ORDER BY AverageSales DESC;
SELECT TOP 5 CustomerName,SUM(SalesAmount) AS TopCustomer  FROM [dbo].[Sales data Analysis using SQL] GROUP BY CustomerName ORDER BY TopCustomer DESC;
